const taskList = document.getElementById('task-list');
const taskError = document.getElementById('task-error');
const statusMessage = document.getElementById('status-message');
const searchInput = document.getElementById('search-input');
const statusFilter = document.getElementById('status-filter');

let tasks = [];

function render() {
  taskList.innerHTML = '';
  let filteredTasks = [];

  for (let task of tasks) {
    if ((statusFilter.value === 'all' || 
        (statusFilter.value === 'active' && !task.completed) || 
        (statusFilter.value === 'completed' && task.completed)) && (task.title.toLowerCase().includes(searchInput.value.toLowerCase()))) {
      filteredTasks.push(task);
    }
  }

  filteredTasks.sort((a, b) => a.title.localeCompare(b.title));

  for (let task of filteredTasks) {
    const li = document.createElement('li');

    const checkbox = document.createElement('input');
    checkbox.type = 'checkbox';
    checkbox.setAttribute('aria-label', 'Complete ' + task.title);
    checkbox.checked = task.completed;
    checkbox.addEventListener('change', function() {
      task.completed = checkbox.checked;
      saveTasks();
      render();
    });

    const span = document.createElement('span');
    span.textContent = task.title;

    li.appendChild(checkbox);
    li.appendChild(span);

    taskList.appendChild(li);
  }

  if (filteredTasks.length === 0) {
    statusMessage.textContent = 'No tasks match your filters.';
  } else {
    statusMessage.textContent = '';
  }
}

function saveTasks() {
  localStorage.setItem('tasks', JSON.stringify(tasks));
}

function loadTasks() {
  const savedTasks = localStorage.getItem('tasks');
  if (savedTasks) {
    tasks = JSON.parse(savedTasks);
  }
}

loadTasks();
render();

searchInput.addEventListener('input', render);
statusFilter.addEventListener('change', render);

document.getElementById('task-form').addEventListener('submit', function(event) {
  event.preventDefault();

  const title = document.getElementById('task-title').value.trim();

  if (!title) {
    taskError.textContent = 'Enter a task title.';
    return;
  }

  taskError.textContent = '';

  const task = {
    title: title,
    completed: false
  };

  tasks.push(task);
  saveTasks();
  render();

  document.getElementById('task-title').value = '';

  // Focus on the next element after the input
  document.querySelector('input[type="text"]').focus();
});

body {
  font-family: Arial, sans-serif;
  margin: 0;
  padding: 0;
  background-color: #f9f9f9;
}

main {
  padding: 2rem;
}

.task {
  padding: 1rem;
  border-bottom: 1px solid #ccc;
}

.task-actions {
  display: flex;
  align-items: center;
}

input[type="text"] {
  padding: 0.5rem;
  margin-right: 1rem;
}

button {
  padding: 0.5rem 1rem;
  background-color: #007bff;
  color: white;
  border: none;
  cursor: pointer;
}

button:hover {
  background-color: #0056b3;
}

#status-message {
  color: red;
  margin-top: 1rem;
}

/* Ensure keyboard navigation and focus states are accessible */
input:focus, button:focus {
  outline: 2px solid #007bff;
  outline-offset: 2px;
}
